import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.Bqn-bhhR.js";const g=JSON.parse('{"title":"Consistent health colors across themes","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-08-04-consistent-health-colors-design.md","filePath":"superpowers/specs/2026-08-04-consistent-health-colors-design.md","lastUpdated":1785878148000}'),i={name:"superpowers/specs/2026-08-04-consistent-health-colors-design.md"};function n(l,e,r,h,d,c){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="consistent-health-colors-across-themes" tabindex="-1">Consistent health colors across themes <a class="header-anchor" href="#consistent-health-colors-across-themes" aria-label="Permalink to &quot;Consistent health colors across themes&quot;">​</a></h1><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to &quot;Problem&quot;">​</a></h2><p>The TUI health indicator conveys a bookmark&#39;s state with color: green = good, yellow = caution, red = bad. Today those colors are not a reliable cue across themes.</p><p>Two theme paths feed the chrome <code>Palette</code>:</p><ul><li><strong>base16/base24 schemes</strong> (<code>theme/base16.rs</code>) — health roles come from canonical slots: <code>base08</code> (red), <code>base0A</code> (yellow), <code>base0B</code> (green). Reliable.</li><li><strong><code>.tmTheme</code> themes</strong> (<code>Palette::from_theme</code> in <code>theme.rs</code>) — the palette is derived from syntax scopes: <code>success</code> from the <em>string</em> scope, <code>warning</code> from the <em>numeric constant</em> scope, <code>error</code> from the <em>invalid</em> scope. None of these are guaranteed to be a green/yellow/red hue. A theme with blue strings yields a blue &quot;healthy&quot; cue, so the health state reads inconsistently.</li></ul><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>Every supported theme must render the health indicator with a real red, yellow, and green. When a theme has no qualifying hue, fall back to fixed defaults.</p><h2 id="approach" tabindex="-1">Approach <a class="header-anchor" href="#approach" aria-label="Permalink to &quot;Approach&quot;">​</a></h2><p>Introduce <strong>dedicated health colors</strong> on the palette, resolved independently of the general <code>success</code>/<code>warning</code>/<code>error</code> roles (which keep their scope-derived meanings for other chrome). This guarantees the semantic cue for health without disturbing chrome that legitimately uses the string/number/invalid colors.</p><h3 id="_1-palette-additions" tabindex="-1">1. Palette additions <a class="header-anchor" href="#_1-palette-additions" aria-label="Permalink to &quot;1. Palette additions&quot;">​</a></h3><p>Add three fields to <code>Palette</code> in <code>theme.rs</code>:</p><div class="language-rust vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">pub</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> health_good</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Color</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// green</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">pub</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> health_warn</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Color</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// yellow</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">pub</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> health_bad</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  Color</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// red</span></span></code></pre></div><p><code>Palette::default()</code> sets them to the ANSI trio (<code>Color::Green</code> / <code>Color::Yellow</code> / <code>Color::Red</code>), so the fallback path and existing rendering are unchanged.</p><h3 id="_2-resolving-the-three-colors-per-theme" tabindex="-1">2. Resolving the three colors per theme <a class="header-anchor" href="#_2-resolving-the-three-colors-per-theme" aria-label="Permalink to &quot;2. Resolving the three colors per theme&quot;">​</a></h3><p><strong>base16 schemes</strong> — <code>Base16Scheme::palette</code> trusts the canonical slots:</p><div class="language-rust vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">health_good</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> c</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0x0B</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// green</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">health_warn</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> c</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0x0A</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// yellow</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">health_bad</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  c</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0x08</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// red</span></span></code></pre></div><p>No hue validation: base16 authors deliberately choose these slots, and a muted-but-intentional red still reads as &quot;the bad one&quot; in context.</p><p><strong><code>.tmTheme</code> themes</strong> — <code>Palette::from_theme</code> searches the theme for the nearest real red/yellow/green:</p><ol><li>Gather a candidate pool of colors from common syntax scopes (<code>string</code>, <code>constant.numeric</code>, <code>constant.language</code>, <code>keyword</code>, <code>entity.name.function</code>, <code>entity.name.type</code>, <code>variable</code>, <code>support.type</code>, <code>invalid</code>) plus the global foreground. Dedupe.</li><li>Convert each candidate to HSL.</li><li>Keep only candidates that clear a <strong>saturation floor</strong> (≈ 0.25) and sit in a <strong>lightness band</strong> (≈ 0.2–0.85), rejecting grays and near-black/near-white.</li><li>Assign each surviving candidate to the <strong>single nearest</strong> target hue — <strong>red ≈ 0°, yellow ≈ 50°, green ≈ 130°</strong> — provided that nearest target is within a <strong>±40° tolerance</strong>. Within each role, keep the closest candidate.</li><li>If a target has no assigned candidate, that field keeps its <code>Palette::default()</code> value (ANSI).</li></ol><p>Assigning to the <em>single nearest</em> target (rather than testing each role independently) is what keeps the three cues distinct. The red and yellow acceptance windows overlap in the orange band (≈ 10°–40°); an independent test would let one orange candidate fill <em>both</em> <code>bad</code> and <code>warn</code> and collapse the distinction. Nearest-target assignment routes that candidate into exactly one role.</p><p>The HSL conversion and hue-matching live in small private helpers in <code>theme.rs</code>, used only by <code>from_theme</code>.</p><h3 id="_3-rewiring-the-health-indicator" tabindex="-1">3. Rewiring the health indicator <a class="header-anchor" href="#_3-rewiring-the-health-indicator" aria-label="Permalink to &quot;3. Rewiring the health indicator&quot;">​</a></h3><p>In <code>component/panel/health.rs</code>, <code>HealthStatus::color()</code> switches the red/yellow/green states from the general roles to the dedicated health fields:</p><table tabindex="0"><thead><tr><th>State</th><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>Healthy</code>, <code>Verified</code></td><td><code>.success</code></td><td><code>.health_good</code></td></tr><tr><td><code>UnanchoredHealthy</code>, <code>Drifted</code>, <code>Outdated</code></td><td><code>.warning</code></td><td><code>.health_warn</code></td></tr><tr><td><code>Broken</code>, <code>BrokenUnanchored</code></td><td><code>.error</code></td><td><code>.health_bad</code></td></tr></tbody></table><p>Unchanged: <code>UnanchoredDrifting</code> → fixed orange, <code>Unknown</code> → <code>.dim</code> (gray), <code>Future</code> → <code>.info</code> (blue). These are outside the red/yellow/green triad, and the orange is already theme-independent.</p><p>Because <code>Palette::default()</code>&#39;s health fields are ANSI Red/Yellow/Green, the existing <code>test_health_status_colors</code> assertions still hold.</p><h2 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h2><ul><li><code>Palette::default()</code> health fields are ANSI Red/Yellow/Green.</li><li><strong>base16</strong>: Catppuccin Mocha / Everforest resolve <code>health_good/warn/bad</code> to base0B/0A/08.</li><li><strong>tmTheme hue search</strong>: a synthetic theme with a clearly green string, red invalid, and yellow constant resolves the health fields to those hues.</li><li><strong>Fallback</strong>: a grayscale-only synthetic theme leaves all three health fields at ANSI.</li><li><strong>Saturation floor</strong>: a desaturated near-gray candidate in the green hue range is rejected in favor of the ANSI fallback.</li><li><strong>Overlap</strong>: a single orange candidate (in the red/yellow overlap band) fills only its nearest role (yellow), leaving the other at its ANSI fallback.</li><li>Existing <code>health.rs</code> color tests updated for the new field routing (values unchanged under the default palette).</li></ul><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of scope&quot;">​</a></h2><ul><li>Changing the <code>success</code>/<code>warning</code>/<code>error</code> roles or other chrome coloring.</li><li>The orange (<code>UnanchoredDrifting</code>), gray (<code>Unknown</code>), and blue (<code>Future</code>) cues.</li><li>Light/dark adaptation beyond what ANSI fallback already provides.</li></ul>`,30)])])}const k=t(i,[["render",n]]);export{g as __pageData,k as default};
